    readOne('/exploitation/invendus?periode=' + per).catch(() => null)
      .then(d => { this._ivEnCours = null; this.setState({ iv: Object.assign({}, this.state.iv || {}, { [per]: { chargement: false, d: d || { error: 'injoignable' } } }) }); });
