      iv.kpi.push(['Pièces jetées', nf(R.pieces), pluriel(R.references || 0, 'référence') + ' · ' + R.declarent + ' magasin' + (R.declarent > 1 ? 's' : '') + ' sur ' + R.magasins + ' déclare' + (R.declarent > 1 ? 'nt' : '') + ' la poubelle']);
