      const an1 = new Date(jeudi.getFullYear(), 0, 4); const num = 1 + Math.round(((jeudi - an1) / 86400000 - 3 + ((an1.getDay() + 6) % 7)) / 7);
      const d1 = c.dates[0], d2 = c.dates[c.dates.length - 1];
