    const fK = n => Math.abs(n) >= 10000 ? (n / 1000).toFixed(1).replace('.', ',') + ' k€' : this.fE(n);
    const pc = (a, b) => b ? 100 * a / b : 0;
    const sg = v => (v >= 0 ? '+' : '−') + Math.abs(Math.round(v));
