            motifs: [{ v: '', nom: 'Choisir le motif…' }].concat(((refs && refs.motifs) || []).map(m => ({ v: m.code, nom: m.nom }))),
            motif: st.motif || '', setMotif: e => patch({ motif: e.target.value }),
